def score_risk(ctx, findings):
    weights = {'none': 0, 'low': 2, 'medium': 8, 'high': 20, 'critical': 40}
    counts = {key: 0 for key in weights}
    score = 0
    actionable = []
    for finding in findings:
        severity = str(finding.get('severity', 'none')).lower()
        severity = severity if severity in weights else 'medium'
        counts[severity] += 1
        score += weights[severity]
        if severity != 'none':
            actionable.append(finding)
    status = 'blocked' if counts['critical'] or score >= 40 else ('review' if score >= 15 else 'ready')
    return {
        'score': score,
        'status': status,
        'counts': counts,
        'actionable_count': len(actionable),
        'release_allowed': status == 'ready',
    }
